#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int a[100005];
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    int key; scanf("%d", &key);
    int ans = -1;
    for (int i = 0; i < n; i++) if (a[i] == key) { ans = i; break; }
    printf("%d\n", ans);
    return 0;
}

