#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n; if (cin >> n) {
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];
        int key; cin >> key;
        int ans = -1;
        for (int i = 0; i < n; i++) if (a[i] == key) { ans = i; break; }
        cout << ans << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = sc.nextInt();
            int key = sc.nextInt();
            int ans = -1;
            for (int i = 0; i < n; i++) if (a[i] == key) { ans = i; break; }
            System.out.println(ans);
        }
    }
}

